package org.example.scheduler;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.example.model.ArticleInfo;
import org.example.service.CaptionService;
import org.example.service.ImageService;
import org.example.service.InstagramService;
import org.example.service.ScraperService;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.List;

@Slf4j
@Component
@RequiredArgsConstructor
public class PostScheduler {

    private static final Path HISTORY = Paths.get("history.txt");
    private static final Path HISTORY     = STORAGE_DIR.resolve("history.txt");

    private final ScraperService scraperService;
    private final ImageService imageService;
    private final InstagramService instagramService;
    private final CaptionService captionService;

    // Fires daily at 10:00 (server timezone): second 0, minute 0, hour 10, every day.
    @Scheduled(cron = "0 0 10 * * *")
    public void run() {
        try {
            log.info("Scheduler triggered");

            ArticleInfo article = scraperService.scrapeLatestArticle();

            if (article.getLink() == null) {
                log.warn("No article link found — skipping");
                return;
            }

            if (alreadyPosted(article.getLink())) {
                log.info("Already posted '{}' — skipping", article.getLink());
                return;
            }

            imageService.generateImage(article);
            imageService.generateStoryImage(article);
            instagramService.postImage(captionService.formatCaption(article.getContent()));
            instagramService.updateProfileWebsite(article.getLink());
            appendHistory(article.getLink());

            log.info("Done: {}", article.getLink());
        } catch (Exception e) {
            log.error("Scheduled post failed", e);
        }
    }

    private boolean alreadyPosted(String link) throws Exception {
        if (!Files.exists(HISTORY)) return false;
        List<String> lines = Files.readAllLines(HISTORY);
        if (lines.isEmpty()) return false;
        return lines.getLast().strip().equals(link.strip());
    }

    private void appendHistory(String link) throws Exception {
        Files.writeString(HISTORY, link + System.lineSeparator(),
                StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }
}

package org.example.scheduler;

import jakarta.annotation.PostConstruct;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.example.model.ArticleInfo;
import org.example.service.CaptionService;
import org.example.service.HistoryService;
import org.example.service.ImageService;
import org.example.service.InstagramService;
import org.example.service.ScraperService;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.concurrent.locks.ReentrantLock;

@Slf4j
@Component
@RequiredArgsConstructor
public class PostScheduler {

    private static final Path STORAGE_DIR = Paths.get("storage");

    private final ScraperService   scraperService;
    private final ImageService     imageService;
    private final InstagramService instagramService;
    private final CaptionService   captionService;
    private final HistoryService   historyService;

    private final ReentrantLock runLock = new ReentrantLock();

    @PostConstruct
    public void init() {
        try {
            Files.createDirectories(STORAGE_DIR);
            log.info("Storage directory ready: {}", STORAGE_DIR.toAbsolutePath());
        } catch (Exception e) {
            log.error("Failed to initialise storage directory", e);
        }
    }

    @EventListener(ApplicationReadyEvent.class)
    public void runOnStartup() {
        log.info("Application ready — running startup publication check");
        Thread thread = new Thread(() -> {
            try {
                run();
            } catch (Exception e) {
                log.error("Startup publication check failed", e);
            }
        }, "startup-publisher");
        thread.setDaemon(false);
        thread.start();
    }

    @Scheduled(cron = "0 0/30 * * * *")
    public void run() {
        if (!runLock.tryLock()) {
            log.info("Scheduler skipped — another run is already in progress");
            return;
        }
        try {
            doRun();
        } finally {
            runLock.unlock();
        }
    }

    private void doRun() {
        try {
            log.info("Scheduler triggered");

            List<ArticleInfo> allArticles = scraperService.scrapeArticles(10);
            if (allArticles.isEmpty()) {
                log.info("No articles returned from Supabase — skipping");
                return;
            }

            // Filter out already-posted articles using HistoryService (backed by GitHub)
            List<ArticleInfo> newArticles = allArticles.stream()
                    .filter(a -> !historyService.isPosted(a.getSlug()))
                    .toList();

            if (newArticles.isEmpty()) {
                log.info("All {} fetched articles already posted — skipping", allArticles.size());
                return;
            }

            // Publish only 1 article per run to avoid OOM (Chromium memory pressure)
            ArticleInfo article = newArticles.get(0);
            log.info("Publishing article ({} new out of {} total): {}",
                    newArticles.size(), allArticles.size(), article.getLink());

            try {
                // Theme: 3 LIGHT → 3 DARK → 3 LIGHT … derived from persistent post count
                boolean isDark = (historyService.getPostedCount() % 6) >= 3;

                // 1. Generate BOTH images in ONE Chromium instance (saves ~250 MB RAM)
                imageService.generateBothImages(article, isDark);

                // 2. Generate caption
                log.info("Generating caption for: {}", article.getTitle());
                String caption = captionService.formatCaption(article.getContent());
                log.info("Caption ready ({} chars), posting feed to Instagram...", caption.length());

                // 3. Publish feed post
                instagramService.postFeed(caption);

                // 4. Mark as posted IMMEDIATELY after feed — even if story fails, no duplicate on next run
                historyService.markAsPosted(article.getSlug());
                log.info("Done (feed): {}", article.getLink());

                // 5. Publish story (best-effort, non-fatal)
                try {
                    instagramService.postStoryOnly();
                    log.info("Done (story): {}", article.getLink());
                } catch (Exception e) {
                    log.warn("Story failed (non-fatal, feed was posted): {}", e.getMessage());
                }

            } catch (Exception e) {
                log.error("Failed to post article '{}' — skipping", article.getLink(), e);
            }

        } catch (Exception e) {
            log.error("Scheduled post failed", e);
        }
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.List;
import java.util.Map;

@Slf4j
@Service
public class CaptionService {

    private static final String API_URL = "https://api.anthropic.com/v1/messages";
    private static final String MODEL   = "claude-haiku-4-5-20251001";

    private static final String CAPTION_SYSTEM = """
            Ты — редактор Instagram-аккаунта «The Vilnius» — русскоязычное городское медиа о Вильнюсе.
            Переформатируй текст новости в Instagram-подпись в профессиональном стиле «The Warsaw».

            Стиль:
            — В начале каждого абзаца ставь 1–2 релевантных эмодзи
            — Тон живой, вовлекающий, профессиональный
            — Между абзацами — пустая строка
            — Используй ПОЛНЫЙ текст новости — без сокращений, без ограничений по длине
            — Сохраняй все ключевые факты, цифры, имена и цитаты из исходника
            — Логичная структура: лид → детали → контекст/последствия

            Строго запрещено:
            — Хэштеги, ссылки, URL
            — Пометки «источник», «читать далее», подписи редакции
            — Любые пояснения от себя — только готовый caption
            """;

    private static final String KEY_PHRASE_SYSTEM = """
            Ты анализируешь русскоязычные заголовки новостей и выделяешь САМУЮ важную, шокирующую
            или интригующую часть, которую нужно подсветить жёлтым маркером в обложке.

            Правила:
            — Верни ТОЛЬКО подстроку из заголовка — без кавычек, без пояснений, без префиксов
            — Подстрока должна точно (буква в букву, регистр и пунктуация) встречаться в заголовке
            — От 1 до 4 идущих подряд слов, без обрывов
            — Выбирай конкретику (имя, цифру, событие, факт), а не служебные слова
              ("в Вильнюсе", "сегодня", "стало известно")
            — Если не уверен — выбери последние 2–3 содержательных слова заголовка

            Примеры:
            Заголовок: Волны краж в Вильнюсе: угнан BMW
            Ответ: угнан BMW

            Заголовок: Цены на жильё снова выросли
            Ответ: снова выросли

            Заголовок: Мэр объявил о массовом ремонте дорог
            Ответ: массовом ремонте дорог
            """;

    @Value("${anthropic.api-key}")
    private String apiKey;

    private final HttpClient http    = HttpClient.newHttpClient();
    private final ObjectMapper mapper = new ObjectMapper();

    public String formatCaption(String rawContent) {
        if (rawContent == null || rawContent.isBlank()) return "";
        try {
            String result = callClaude(CAPTION_SYSTEM, rawContent, 4096);
            log.info("Caption formatted ({} chars)", result.length());
            return result;
        } catch (Exception e) {
            log.error("Caption LLM call failed — falling back to raw content", e);
            return rawContent;
        }
    }

    public String findKeyPhrase(String title) {
        if (title == null || title.isBlank()) return null;
        try {
            String raw = callClaude(KEY_PHRASE_SYSTEM, title, 64).strip();
            String phrase = raw.replaceAll("^[\"'«»\\s]+", "").replaceAll("[\"'«»\\s]+$", "");
            if (phrase.isBlank() || !title.contains(phrase)) {
                log.warn("Key phrase '{}' not a substring of title '{}' — using fallback", phrase, title);
                return null;
            }
            log.info("Key phrase: '{}'", phrase);
            return phrase;
        } catch (Exception e) {
            log.error("Key phrase LLM call failed — falling back to last words", e);
            return null;
        }
    }

    private String callClaude(String system, String userContent, int maxTokens) throws Exception {
        String systemJson = mapper.writeValueAsString(List.of(
                Map.of("type", "text",
                       "text", system,
                       "cache_control", Map.of("type", "ephemeral"))
        ));
        String userJson = mapper.writeValueAsString(userContent);

        String body = """
                {"model":"%s","max_tokens":%d,"system":%s,"messages":[{"role":"user","content":%s}]}
                """.formatted(MODEL, maxTokens, systemJson, userJson).strip();

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(API_URL))
                .header("x-api-key", apiKey)
                .header("anthropic-version", "2023-06-01")
                .header("anthropic-beta", "prompt-caching-2024-07-31")
                .header("content-type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();

        HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
        JsonNode json = mapper.readTree(response.body());

        if (json.has("error")) {
            throw new RuntimeException("Claude API error: " + response.body());
        }
        return json.path("content").get(0).path("text").asText();
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

@Slf4j
@Service
public class CaptionService {

    private static final String API_URL_TEMPLATE =
            "https://generativelanguage.googleapis.com/v1/models/gemini-2.5-flash-lite:generateContent?key=%s";

    private static final String CAPTION_SYSTEM = """
            Ты — редактор Instagram-аккаунта «The Vilnius» — русскоязычное городское медиа о Вильнюсе.
            Переформатируй текст новости в Instagram-подпись в профессиональном стиле «The Warsaw».

            Стиль:
            — В начале каждого абзаца ставь 1–2 релевантных эмодзи
            — Тон живой, вовлекающий, профессиональный
            — Между абзацами — пустая строка
            — Используй ПОЛНЫЙ текст новости — без сокращений, без ограничений по длине
            — Сохраняй все ключевые факты, цифры, имена и цитаты из исходника
            — Логичная структура: лид → детали → контекст/последствия

            Строго запрещено:
            — Хэштеги, ссылки, URL
            — Пометки «источник», «читать далее», подписи редакции
            — Любые пояснения от себя — только готовый caption
            """;

    private static final String KEY_PHRASE_SYSTEM = """
            Ты анализируешь русскоязычные заголовки новостей и выделяешь САМУЮ важную, шокирующую
            или интригующую часть, которую нужно подсветить жёлтым маркером в обложке.

            Правила:
            — Верни ТОЛЬКО подстроку из заголовка — без кавычек, без пояснений, без префиксов
            — Подстрока должна точно (буква в букву, регистр и пунктуация) встречаться в заголовке
            — От 1 до 4 идущих подряд слов, без обрывов
            — Выбирай конкретику (имя, цифру, событие, факт), а не служебные слова
              ("в Вильнюсе", "сегодня", "стало известно")
            — Если не уверен — выбери последние 2–3 содержательных слова заголовка

            Примеры:
            Заголовок: Волны краж в Вильнюсе: угнан BMW
            Ответ: угнан BMW

            Заголовок: Цены на жильё снова выросли
            Ответ: снова выросли

            Заголовок: Мэр объявил о массовом ремонте дорог
            Ответ: массовом ремонте дорог
            """;

    @Value("${gemini.api-key:}")
    private String apiKey;

    private final HttpClient    http   = HttpClient.newHttpClient();
    private final ObjectMapper  mapper = new ObjectMapper();

    @PostConstruct
    public void validateApiKey() {
        if (apiKey == null || apiKey.isBlank()) {
            log.warn("⚠️  gemini.api-key is not set — caption/key-phrase generation will be skipped. " +
                     "Set the GEMINI_API_KEY environment variable to enable AI features.");
        } else {
            log.info("Gemini API configured (gemini-2.5-flash-lite)");
        }
    }

    public String formatCaption(String rawContent) {
        if (rawContent == null || rawContent.isBlank()) return "";
        if (apiKey == null || apiKey.isBlank()) {
            log.warn("Gemini API key not set — returning raw content as caption");
            return truncate(rawContent);
        }
        try {
            String result = callGemini(CAPTION_SYSTEM, rawContent, 4096);
            result = truncate(result);
            log.info("Caption formatted ({} chars)", result.length());
            return result;
        } catch (Exception e) {
            log.error("Caption Gemini call failed — falling back to raw content", e);
            return truncate(rawContent);
        }
    }

    /** Hard-trims caption to Instagram's 2200-char limit, cutting at the last newline before the limit. */
    private static String truncate(String text) {
        if (text == null || text.length() <= INSTAGRAM_MAX_CAPTION) return text;
        String cut = text.substring(0, INSTAGRAM_MAX_CAPTION);
        int lastNl = cut.lastIndexOf('\n');
        return (lastNl > INSTAGRAM_MAX_CAPTION / 2 ? cut.substring(0, lastNl) : cut).stripTrailing();
    }

    public String findKeyPhrase(String title) {
        if (title == null || title.isBlank()) return null;
        if (apiKey == null || apiKey.isBlank()) {
            log.warn("Gemini API key not set — skipping key-phrase detection");
            return null;
        }
        try {
            String raw    = callGemini(KEY_PHRASE_SYSTEM, title, 64).strip();
            String phrase = raw.replaceAll("^[\"'«»\\s]+", "").replaceAll("[\"'«»\\s]+$", "");
            if (phrase.isBlank() || !title.contains(phrase)) {
                log.warn("Key phrase '{}' not a substring of title '{}' — using fallback", phrase, title);
                return null;
            }
            log.info("Key phrase: '{}'", phrase);
            return phrase;
        } catch (Exception e) {
            log.error("Key phrase Gemini call failed — falling back to last words", e);
            return null;
        }
    }

    /**
     * Calls the Gemini REST API (no SDK needed — plain HTTP).
     * Endpoint: POST https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=...
     */
    private String callGemini(String systemPrompt, String userContent, int maxOutputTokens) throws Exception {
        // Combine system prompt + user content into a single user message (v1 doesn't support systemInstruction)
        String combinedText = systemPrompt.strip() + "\n\n" + userContent;

        String body = mapper.writeValueAsString(java.util.Map.of(
                "contents", java.util.List.of(java.util.Map.of(
                        "role", "user",
                        "parts", java.util.List.of(java.util.Map.of("text", combinedText))
                )),
                "generationConfig", java.util.Map.of(
                        "maxOutputTokens", maxOutputTokens,
                        "temperature", 0.7
                )
        ));

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(API_URL_TEMPLATE.formatted(apiKey)))
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();

        HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
        JsonNode json = mapper.readTree(response.body());

        // Surface API errors clearly
        if (json.has("error")) {
            String errorMsg = json.path("error").path("message").asText(response.body());
            throw new RuntimeException("Gemini API error (%d): %s".formatted(response.statusCode(), errorMsg));
        }

        return json.path("candidates").get(0)
                   .path("content").path("parts").get(0)
                   .path("text").asText();
    }
}

package org.example.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.Duration;
import java.util.Base64;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * Persists posted article slugs with two layers:
 *  1. LOCAL  — storage/posted_slugs.json  (fast, survives restarts within same Render instance)
 *  2. GITHUB — data/posted_slugs.json in the repo (survives re-deploys)
 *
 * On startup: loads from GitHub first, then merges with local file.
 * On save:    writes local file first (fast), then uploads to GitHub (best-effort).
 */
@Slf4j
@Service
public class HistoryService {

    @Value("${github.token}")
    private String githubToken;

    @Value("${github.repo.owner}")
    private String repoOwner;

    @Value("${github.repo.name}")
    private String repoName;

    private static final String   GITHUB_FILE_PATH = "data/posted_slugs.json";
    private static final String   API_BASE         = "https://api.github.com";
    private static final Path     LOCAL_FILE       = Paths.get("storage/posted_slugs.json");

    private final HttpClient   http   = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(15))
            .build();
    private final ObjectMapper mapper = new ObjectMapper();

    private final Set<String> posted = Collections.synchronizedSet(new HashSet<>());
    private String currentSha = null;

    @PostConstruct
    public void init() {
        loadFromGitHub();   // primary source (persistent across redeploys)
        loadFromLocal();    // merge with local (survives restarts within same instance)
        log.info("HistoryService ready — {} slugs loaded", posted.size());
    }

    public boolean isPosted(String slug) {
        return slug != null && posted.contains(slug);
    }

    /** Total number of articles posted so far — used to determine LIGHT/DARK theme rotation. */
    public int getPostedCount() {
        return posted.size();
    }

    public void markAsPosted(String slug) {
        if (slug == null || slug.isBlank()) return;
        posted.add(slug);
        saveToLocal();      // fast, always works
        saveToGitHub();     // persistent across redeploys (requires token write access)
        log.info("Marked as posted: slug='{}'  (total history: {})", slug, posted.size());
    }

    // ────────────────────────────────────────────────────────────────────────────
    // Local file (storage/posted_slugs.json)
    // ────────────────────────────────────────────────────────────────────────────

    private void loadFromLocal() {
        try {
            if (Files.exists(LOCAL_FILE)) {
                String[] slugs = mapper.readValue(LOCAL_FILE.toFile(), String[].class);
                int before = posted.size();
                for (String s : slugs) posted.add(s);
                log.info("Merged {} slugs from local file (total: {})", posted.size() - before, posted.size());
            }
        } catch (Exception e) {
            log.warn("Could not load local history file: {}", e.getMessage());
        }
    }

    private void saveToLocal() {
        try {
            Files.createDirectories(LOCAL_FILE.getParent());
            mapper.writeValue(LOCAL_FILE.toFile(), posted);
        } catch (Exception e) {
            log.warn("Could not save local history file: {}", e.getMessage());
        }
    }

    // ────────────────────────────────────────────────────────────────────────────
    // GitHub Contents API (data/posted_slugs.json in repo)
    // ────────────────────────────────────────────────────────────────────────────

    private void loadFromGitHub() {
        try {
            String url = API_BASE + "/repos/" + repoOwner + "/" + repoName
                    + "/contents/" + GITHUB_FILE_PATH;

            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create(url))
                    .timeout(Duration.ofSeconds(10))
                    .header("Authorization", "Bearer " + githubToken)
                    .header("Accept", "application/vnd.github+json")
                    .header("X-GitHub-Api-Version", "2022-11-28")
                    .GET()
                    .build();

            HttpResponse<String> res = http.send(req, HttpResponse.BodyHandlers.ofString());

            if (res.statusCode() == 200) {
                JsonNode json = mapper.readTree(res.body());
                currentSha = json.path("sha").asText(null);
                String content = json.path("content").asText("").replaceAll("\\s", "");
                String decoded = new String(Base64.getDecoder().decode(content));
                String[] slugs = mapper.readValue(decoded, String[].class);
                for (String s : slugs) posted.add(s);
                log.info("Loaded {} posted slugs from GitHub (sha={})", posted.size(), currentSha);
            } else if (res.statusCode() == 404) {
                log.info("No history file yet in GitHub — starting fresh");
            } else if (res.statusCode() == 403 || res.statusCode() == 401) {
                log.warn("GitHub token has no READ access to repo contents (status={}). " +
                         "Fix: GitHub → token → Repository permissions → Contents → Read and Write",
                         res.statusCode());
            } else {
                log.warn("Unexpected status loading history from GitHub: {} — {}",
                        res.statusCode(), res.body());
            }
        } catch (Exception e) {
            log.warn("Could not load history from GitHub: {}", e.getMessage());
        }
    }

    private void saveToGitHub() {
        try {
            String url = API_BASE + "/repos/" + repoOwner + "/" + repoName
                    + "/contents/" + GITHUB_FILE_PATH;

            String jsonContent = mapper.writeValueAsString(posted);
            String encoded     = Base64.getEncoder().encodeToString(jsonContent.getBytes());

            StringBuilder body = new StringBuilder();
            body.append("{")
                .append("\"message\":\"chore: update posted slugs history\",")
                .append("\"content\":\"").append(encoded).append("\"");
            if (currentSha != null) {
                body.append(",\"sha\":\"").append(currentSha).append("\"");
            }
            body.append("}");

            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create(url))
                    .timeout(Duration.ofSeconds(15))
                    .header("Authorization", "Bearer " + githubToken)
                    .header("Accept", "application/vnd.github+json")
                    .header("X-GitHub-Api-Version", "2022-11-28")
                    .header("Content-Type", "application/json")
                    .PUT(HttpRequest.BodyPublishers.ofString(body.toString()))
                    .build();

            HttpResponse<String> res = http.send(req, HttpResponse.BodyHandlers.ofString());

            if (res.statusCode() == 200 || res.statusCode() == 201) {
                JsonNode json = mapper.readTree(res.body());
                currentSha = json.path("content").path("sha").asText(currentSha);
                log.info("History saved to GitHub ({} slugs, sha={})", posted.size(), currentSha);
            } else if (res.statusCode() == 403 || res.statusCode() == 401) {
                log.warn("GitHub token has no WRITE access (status={}). History saved locally only. " +
                         "Fix: GitHub → token → Repository permissions → Contents → Read and Write",
                         res.statusCode());
            } else {
                log.warn("Failed to save history to GitHub: status={}, body={}",
                        res.statusCode(), res.body());
            }
        } catch (Exception e) {
            log.warn("Could not save history to GitHub: {}", e.getMessage());
        }
    }
}

package org.example.service;

import com.microsoft.playwright.Browser;
import com.microsoft.playwright.BrowserContext;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.Playwright;
import com.microsoft.playwright.options.LoadState;
import com.microsoft.playwright.options.ScreenshotType;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.example.model.ArticleInfo;
import org.springframework.stereotype.Service;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.Arrays;

@Slf4j
@Service
@RequiredArgsConstructor
public class ImageService {

    private static final String STORAGE_DIR = "storage";
    public static final String OUTPUT_FILENAME = "upload.png";
    public static final String STORY_FILENAME = "story_upload.png";
    private static final Path COUNTER_FILE = Paths.get(STORAGE_DIR, "theme_counter.txt");

    private enum Theme { LIGHT, DARK }

    private Theme lastTheme = Theme.LIGHT;

    private final CaptionService captionService;

    public Path generateImage(ArticleInfo article) throws Exception {
        Path storageDir = Paths.get(STORAGE_DIR);
        Files.createDirectories(storageDir);

        ensureKeyPhrase(article);

        Theme theme = nextTheme();
        lastTheme = theme;
        log.info("Using {} theme", theme);

        String html = theme == Theme.DARK ? buildDarkHtml(article) : buildLightHtml(article);

        Path outputPath = storageDir.resolve(OUTPUT_FILENAME);
        Path previewPath = storageDir.resolve("grid_preview.png");

        // Force fresh generation: delete any cached output before re-rendering
        Files.deleteIfExists(outputPath);
        Files.deleteIfExists(previewPath);

        try (Playwright playwright = Playwright.create()) {
            try (Browser browser = playwright.chromium().launch()) {
                BrowserContext ctx = browser.newContext(
                        new Browser.NewContextOptions().setViewportSize(1080, 1350));
                Page page = ctx.newPage();
                page.setContent(html);
                page.waitForLoadState(LoadState.NETWORKIDLE,
                        new Page.WaitForLoadStateOptions().setTimeout(10_000));
                page.screenshot(new Page.ScreenshotOptions()
                        .setPath(outputPath)
                        .setType(ScreenshotType.PNG));

                // 1:1 grid-crop preview: Instagram profile grid shows the centered
                // 1080×1080 region of the 1080×1350 post (Y=135 .. Y=1215).
                page.screenshot(new Page.ScreenshotOptions()
                        .setPath(previewPath)
                        .setClip(0, 135, 1080, 1080)
                        .setType(ScreenshotType.PNG));
            }
        }

        log.info("Image saved: {} ({})", outputPath.toAbsolutePath(), theme);
        log.info("Grid preview saved: {} (1080x1080 crop, Y=135..Y=1215; logo top at Y=200 is inside the crop)",
                previewPath.toAbsolutePath());
        return outputPath;
    }

    // Counter cycles 0–5: 0,1,2 → LIGHT; 3,4,5 → DARK
    private Theme nextTheme() throws Exception {
        int count = 0;
        if (Files.exists(COUNTER_FILE)) {
            String s = Files.readString(COUNTER_FILE).trim();
            if (!s.isEmpty()) count = Integer.parseInt(s);
        }
        Theme theme = (count % 6) < 3 ? Theme.LIGHT : Theme.DARK;
        Files.writeString(COUNTER_FILE, String.valueOf((count + 1) % 6),
                StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
        return theme;
    }

    public Path generateStoryImage(ArticleInfo article) throws Exception {
        Path storageDir = Paths.get(STORAGE_DIR);
        Files.createDirectories(storageDir);

        ensureKeyPhrase(article);

        String html = lastTheme == Theme.DARK
                ? buildDarkStoryHtml(article)
                : buildLightStoryHtml(article);

        Path outputPath = storageDir.resolve(STORY_FILENAME);

        try (Playwright playwright = Playwright.create()) {
            try (Browser browser = playwright.chromium().launch()) {
                BrowserContext ctx = browser.newContext(
                        new Browser.NewContextOptions().setViewportSize(1080, 1920));
                Page page = ctx.newPage();
                page.setContent(html);
                page.waitForLoadState(LoadState.NETWORKIDLE,
                        new Page.WaitForLoadStateOptions().setTimeout(10_000));
                page.screenshot(new Page.ScreenshotOptions()
                        .setPath(outputPath)
                        .setType(ScreenshotType.PNG));
            }
        }

        log.info("Story image saved: {} ({})", outputPath.toAbsolutePath(), lastTheme);
        return outputPath;
    }

    // Computes the key phrase once per article (LLM call) and stores it on the model.
    private void ensureKeyPhrase(ArticleInfo article) {
        if (article.getKeyPhrase() != null) return;
        article.setKeyPhrase(captionService.findKeyPhrase(article.getTitle()));
    }

    // Wraps the LLM-identified key phrase in a yellow highlight span.
    // Falls back to the last 3 words if no phrase is provided.
    private String buildTitleHtml(String title, String keyPhrase) {
        String safeTitle = escapeHtml(title);
        if (keyPhrase != null && !keyPhrase.isBlank()) {
            String safePhrase = escapeHtml(keyPhrase);
            int idx = safeTitle.indexOf(safePhrase);
            if (idx >= 0) {
                return safeTitle.substring(0, idx)
                        + "<span class=\"hl\">" + safePhrase + "</span>"
                        + safeTitle.substring(idx + safePhrase.length());
            }
        }
        String[] words = safeTitle.split(" ");
        if (words.length <= 3) {
            return "<span class=\"hl\">" + safeTitle + "</span>";
        }
        String normal = String.join(" ", Arrays.copyOf(words, words.length - 3));
        String highlighted = String.join(" ", Arrays.copyOfRange(words, words.length - 3, words.length));
        return normal + " <span class=\"hl\">" + highlighted + "</span>";
    }

    private static String escapeHtml(String s) {
        return s == null ? "" : s
                .replace("&", "&amp;").replace("<", "&lt;")
                .replace(">", "&gt;").replace("\"", "&quot;");
    }

    private String buildDarkHtml(ArticleInfo article) {
        String safeImage = safeImage(article.getImageUrl());
        return """
                <!DOCTYPE html>
                <html>
                <head>
                <meta charset="UTF-8">
                <link rel="preconnect" href="https://fonts.googleapis.com">
                <link href="https://fonts.googleapis.com/css2?family=League+Spartan:wght@400;700&display=swap" rel="stylesheet">
